#!/usr/bin/env python3
"""Genera todas las páginas desde datos y componentes compartidos. Sin dependencias."""
from pathlib import Path
from html import escape as e
from urllib.parse import quote
import json
ROOT=Path(__file__).resolve().parents[1]
D=ROOT/'docs'
PAGES=json.loads((ROOT/'content-pages.json').read_text())
BASE='https://www.credisnet.com.ar/'
WA='https://wa.me/541122845514?text='
def contact(label='Consultar por WhatsApp', topic='préstamos por descuento de haberes', cls='button'):
 return f'<a class="{cls}" href="{WA}{quote("Hola, quisiera consultar sobre "+topic+".")}" target="_blank" rel="noopener noreferrer">{label} <span aria-hidden="true">↗</span></a>'
def layout(title,desc,body,slug=''):
 pre='../' if slug else './'
 url=BASE+(slug+'/' if slug else '')
 schema={'@context':'https://schema.org','@type':'WebPage','name':title,'url':url,'inLanguage':'es-AR','publisher':{'@type':'Organization','name':'Credisnet','url':BASE}}
 return f'''<!doctype html><html lang="es-AR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{url}"><meta name="robots" content="index,follow"><meta name="theme-color" content="#123f35"><meta property="og:type" content="website"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}img/familia.webp"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="{pre}icons/favicon-32.png"><link rel="stylesheet" href="{pre}css/site.css"><script src="{pre}js/site.js" defer></script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head><body><a class="skip" href="#contenido">Saltar al contenido</a><div class="topline">Préstamos por descuento de haberes <span>Atención online · Argentina</span></div><header class="header"><a class="brand" href="{pre}" aria-label="Credisnet, inicio"><span class="brand-icon" aria-hidden="true">c<span>↗</span></span>credisnet<span class="brand-dot">.</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menú <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Navegación principal"><a href="{pre}#sectores">Para quiénes</a><a href="{pre}#como-funciona">Cómo funciona</a><a href="{pre}quienes-somos/">Nosotros</a><a href="{pre}preguntas-frecuentes/">Preguntas frecuentes</a>{contact('Hablemos',cls='button small')}</nav></header><main id="contenido">{body}</main><footer><div class="footer-grid"><div><a class="brand" href="{pre}">credisnet.</a><p>Tu próximo paso,<br>con información clara.</p><small>Comercializadora de créditos.<br>Credisnet no es un banco ni una entidad financiera.</small></div><div><h2>Explorá</h2><a href="{pre}#sectores">Líneas de préstamos</a><a href="{pre}quienes-somos/">Quiénes somos</a><a href="{pre}preguntas-frecuentes/">Preguntas frecuentes</a></div><div><h2>Información</h2><a href="{pre}informacion-financiera/">Información financiera</a><a href="{pre}politica-de-privacidad/">Privacidad</a><a href="{pre}terminos-y-condiciones/">Términos y condiciones</a></div><div><h2>Estamos para ayudarte</h2><a href="mailto:info@credisnet.com">info@credisnet.com</a><a href="https://wa.me/541169707265" target="_blank" rel="noopener noreferrer">+54 11 6970-7265</a><p>Buenos Aires, Argentina</p></div></div><div class="footer-bottom">© 2026 Credisnet <span>Operaciones sujetas a evaluación y aprobación de la entidad otorgante.</span></div></footer></body></html>'''
def faq():
 items=[('¿Cómo funciona el descuento de haberes?','La cuota se descuenta del recibo de sueldo o haberes según la operatoria habilitada por tu organismo. Antes de avanzar, consultá las condiciones aplicables a tu caso.'),('¿Puedo saber cuánto tengo disponible?','Sí. Un asesor puede orientarte según tu organismo y situación. El monto y el plazo dependen de la evaluación y aprobación de la entidad otorgante.'),('¿La consulta implica contratar un préstamo?','No. Podés consultar y revisar las condiciones antes de decidir si querés avanzar.'),('¿Qué documentación pueden solicitarme?','Según la línea, pueden solicitarte DNI, recibo de haberes y constancia de CBU. Confirmá con el asesor los requisitos específicos y el canal de envío antes de compartir documentación.'),('¿Quién otorga y acredita el préstamo?','Credisnet gestiona la consulta y el legajo. La entidad otorgante evalúa la solicitud, define las condiciones y acredita los fondos si aprueba la operación.'),('¿Qué debo revisar antes de aceptar?','Revisá el monto a recibir, el costo financiero total, las tasas, la cantidad de cuotas, el total a devolver y las condiciones de cancelación y mora.')]
 return ''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in items)
def process():
 return '<section class="section" id="como-funciona"><div class="section-head"><div><p class="eyebrow">SIMPLE, DE PRINCIPIO A FIN</p><h2>Un camino claro.<br>Una decisión tuya.</h2></div><p>Te acompañamos en cada paso.<br>Vos decidís cuándo avanzar.</p></div><div class="steps">'+''.join(f'<article><span class="step-number">0{i}</span><h3>{t}</h3><p>{d}</p></article>' for i,t,d in [(1,'Contanos sobre vos','Elegí tu sector y hablá con un asesor sobre tu consulta.'),(2,'Conocé tus opciones','Revisá el monto, las cuotas y los costos de la propuesta.'),(3,'Presentá tu solicitud','Si decidís avanzar, te orientamos para armar tu legajo.'),(4,'Recibí la respuesta','La entidad evalúa y, si aprueba, acredita en tu cuenta.')])+'</div></section>'
def endcta():
 return '<section class="cta section"><div><p class="eyebrow">EL PRIMER PASO ES UNA CONVERSACIÓN</p><h2>Hablemos de lo que<br>tenés en mente.</h2><p>Consultá tus opciones y decidí con información.</p></div>'+contact()+'</section>'
def card(p,i):
 return f'<a class="sector-card" href="./{p["slug"]}/" data-sector="{e(p["title"].lower())}"><span class="card-number">{i:02d}</span><h3>{e(p["title"])}</h3><span class="card-bottom">Conocer esta línea <span aria-hidden="true">↗</span></span></a>'
def home():
 loans=PAGES[:19]
 cards=''.join(card(p,i+1) for i,p in enumerate(loans))
 options=''.join(f'<option value="{p["slug"]}">{e(p["title"])}</option>' for p in loans)
 body=f'''<section class="hero section"><div class="hero-copy"><p class="eyebrow"><span class="status-dot"></span> CERCA TUYO, DONDE ESTÉS</p><h1>Un impulso para<br>lo que <em>viene.</em></h1><p class="hero-description">Préstamos por descuento de haberes para quienes trabajan en el sector público, fuerzas y beneficiarios de las líneas disponibles.</p><div class="hero-actions">{contact('Consultá tus opciones')}<a class="text-link" href="#sectores">Encontrá tu sector <span aria-hidden="true">↓</span></a></div><p class="fine">Consulta sin compromiso. Sujeto a evaluación crediticia.</p><div class="hero-points"><span>Gestión online</span><span>Atención personal</span><span>Información clara</span></div></div><div class="hero-visual"><img src="./img/familia.webp" width="3836" height="1120" alt="Una familia compartiendo un momento en casa" fetchpriority="high"><div class="image-label"><span class="status-dot"></span> Tus proyectos, más cerca.</div><div class="visual-note"><span aria-hidden="true">↗</span><div>Vos elegís el próximo paso.<small>Nosotros te acompañamos.</small></div></div></div></section><section class="finder section" aria-labelledby="finder-title"><div><p class="eyebrow">EMPEZÁ POR ACÁ</p><h2 id="finder-title">Una opción para tu sector.</h2><p>Seleccioná tu organismo para conocer más.</p></div><form id="sector-form" action="./" method="get"><label for="sector-select">¿A qué sector pertenecés?</label><div class="input-row"><select id="sector-select" name="sector" required><option value="">Elegí tu sector</option>{options}</select><button class="button" type="submit">Ver mi línea <span aria-hidden="true">→</span></button></div><p class="fine">No necesitás ingresar datos personales.</p></form></section><section class="section" id="sectores"><div class="section-head"><div><p class="eyebrow">ENCONTRÁ TU LÍNEA</p><h2>Distintos caminos.<br>La misma atención.</h2></div><div class="search-box"><label for="sector-search">Buscá tu organismo</label><input type="search" id="sector-search" placeholder="Ej.: docentes, policía, IPS" autocomplete="off"></div></div><p id="search-status" class="sr-only" role="status" aria-live="polite"></p><div class="sector-grid">{cards}</div><p id="empty-state" hidden>No encontramos ese organismo. Probá otra palabra o <a href="https://wa.me/541122845514">consultanos por WhatsApp</a>.</p><noscript><p>Podés recorrer todas las líneas en esta sección.</p></noscript></section><section class="about section"><div class="about-image"><img src="./img/fuerzas.webp" width="3836" height="1120" alt="Personal de las fuerzas, uno de los sectores a los que orienta Credisnet" loading="lazy"></div><div><p class="eyebrow">ACOMPAÑAMIENTO PERSONAL</p><h2>Detrás de cada consulta,<br>hay una persona.</h2><p>Por eso, empezamos por escucharte. En Credisnet te orientamos en la gestión de préstamos por descuento de haberes, con atención online y un proceso que podés entender.</p><ul class="check-list"><li>Conocé las condiciones antes de decidir.</li><li>Consultá los requisitos de tu organismo.</li><li>Recibí orientación para preparar tu solicitud.</li></ul><a class="text-link" href="./quienes-somos/">Conocé Credisnet <span aria-hidden="true">↗</span></a></div></section>{process()}<section class="finance section"><div><p class="eyebrow">DECIDÍ CON INFORMACIÓN</p><h2>Más claridad.<br>Mejores decisiones.</h2></div><div><p>Antes de aceptar una propuesta, revisá el Costo Financiero Total, las cuotas y el total a devolver. El monto y las condiciones dependen de cada entidad y de tu evaluación.</p><a class="text-link" href="./informacion-financiera/">Qué mirar antes de contratar ↗</a></div></section><section class="section faq-section"><div><p class="eyebrow">DESPEJÁ TUS DUDAS</p><h2>Primero, las<br>respuestas.</h2><a class="text-link" href="./preguntas-frecuentes/">Más información ↗</a></div><div>{faq()}</div></section>{endcta()}'''
 (D/'index.html').write_text(layout('Credisnet | Préstamos por descuento de haberes','Conocé las líneas para empleados públicos, docentes, fuerzas y jubilados IPS. Consultá a Credisnet por WhatsApp y revisá tus opciones.',body))
def inner(p):
 slug=p['slug']; title=p['title']; pre='../'
 intro='Información para avanzar con claridad.'
 if slug.startswith('prestamos-'):
  intro=f'Conocé las opciones de préstamos por descuento de haberes para {title.lower()}. Consultá la disponibilidad para tu organismo y situación.'
  content=f'<div class="content-grid"><article class="prose"><h2>Tu consulta, paso a paso</h2><p>En Credisnet te orientamos para gestionar una solicitud de préstamo. La disponibilidad depende del convenio aplicable, tu situación de revista, el margen de descuento y la evaluación de la entidad otorgante.</p><h2>¿Qué necesitás consultar?</h2><ul><li>Si tu organismo y situación están incluidos en la línea.</li><li>Qué documentación se requiere para evaluar tu solicitud.</li><li>El monto disponible, plazo, cuotas y costo financiero total.</li><li>Las condiciones del contrato y de cancelación.</li></ul><h2>Documentación orientativa</h2><p>Podrían solicitarte DNI, último recibo de haberes y constancia de CBU. Los requisitos específicos se confirman durante el asesoramiento. No envíes claves bancarias ni códigos de seguridad.</p><h2>Condiciones que tenés que conocer</h2><p>Consultar no equivale a una aprobación. Los montos, tasas, costos y plazos se informan en la propuesta de la entidad antes de contratar. La acreditación depende de la aprobación y los tiempos de esa entidad.</p><a class="text-link" href="../informacion-financiera/">Leé la información financiera ↗</a></article><aside class="consult-card"><span class="eyebrow">TU LÍNEA</span><h2>{e(title)}</h2><p>Contanos tu situación y consultá qué opciones están disponibles.</p>{contact('Consultar esta línea',title)}<small>Sin compromiso. Sujeto a evaluación.<br>La consulta se abre en WhatsApp.</small></aside></div>{process()}'
 elif slug=='preguntas-frecuentes': content='<div class="prose faq-page">'+faq()+'</div>'
 elif slug=='quienes-somos':
  intro='Personas que acompañan a personas.'
  content='<div class="content-grid"><article class="prose"><h2>Somos Credisnet</h2><p>Somos una comercializadora de créditos enfocada en la gestión de préstamos por descuento de haberes para el sector público, fuerzas y beneficiarios de las líneas disponibles.</p><p>Te orientamos desde la consulta inicial hasta la presentación del legajo. La evaluación y el otorgamiento del préstamo están a cargo de la entidad correspondiente.</p><h2>Una atención que empieza por escucharte</h2><p>Trabajamos de manera online para que puedas consultar los requisitos y revisar las condiciones sin necesidad de una visita presencial.</p><h2>Canales de contacto</h2><p>Para nuevas consultas, usá el botón de WhatsApp. Para contacto general, escribinos a info@credisnet.com o al +54 11 6970-7265.</p></article><img class="inner-image" src="../img/familia.webp" width="3836" height="1120" alt="Familia compartiendo un momento en casa"></div>'
 else: content='<article class="prose legal">'+(ROOT/'data'/f'{slug}.html').read_text()+'</article>'
 body=f'<section class="page-hero section"><nav class="breadcrumb" aria-label="Ruta de navegación"><a href="../">Inicio</a><span aria-hidden="true">/</span><span>{e(title)}</span></nav><p class="eyebrow">CREDISNET · {"LÍNEAS DE PRÉSTAMOS" if slug.startswith("prestamos-") else "INFORMACIÓN"}</p><h1>{"Préstamos para " if slug.startswith("prestamos-") else ""}{e(title)}</h1><p>{intro}</p></section><section class="section page-content">{content}</section>{endcta()}'
 path=D/slug; path.mkdir(exist_ok=True)
 (path/'index.html').write_text(layout(title+' | Credisnet',intro,body,slug))
if __name__=='__main__':
 home()
 for p in PAGES: inner(p)
 (D/'404.html').write_text('<!doctype html><html lang="es-AR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><title>Página no encontrada | Credisnet</title><style>body{margin:0;background:#fafbf6;color:#153d34;font:18px/1.6 Arial,sans-serif}main{max-width:700px;margin:15vh auto;padding:30px}h1{font-size:clamp(38px,7vw,65px);line-height:1.1;letter-spacing:-2px}a{display:inline-block;padding:14px 24px;background:#153d34;color:white;border-radius:8px}a:focus-visible{outline:3px solid #b15e20;outline-offset:5px}</style></head><body><main><p>CREDISNET · ERROR 404</p><h1>Busquemos otro camino.</h1><p>La dirección no existe o cambió. Volvé al inicio para encontrar tu línea.</p><a id="home" href="/">Volver al inicio →</a></main><script>if(location.hostname.endsWith(\'.github.io\')){const segment=location.pathname.split(\'/\').filter(Boolean)[0];if(segment)document.getElementById(\'home\').href=\'/\'+encodeURIComponent(segment)+\'/\';}</script></body></html>')
 print('Generadas 26 páginas')
